module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output reg [7:0] out
);

    wire [7:0] shift4, shift2, shift1;

    assign shift4 = {in[3:0], in[7:4]};
    assign shift2 = {in[1:0], in[7:2]};
    assign shift1 = {in[0], in[7:1]};

    assign out = (ctrl[2]) ? shift4 :
                (ctrl[1]) ? shift2 :
                (ctrl[0]) ? shift1 :
                             in;

endmodule

module barrel_shifter_tb;

    reg [7:0] in;
    reg [2:0] ctrl;

    wire [7:0] out;

    barrel_shifter dut (
        .in(in),
        .ctrl(ctrl),
        .out(out)
    );

    initial begin

        in = 8'b00000000;
        ctrl = 3'b000;

        #100;

        in = 8'h55;
        ctrl = 3'b001; 
        #100;

        in = 8'h55;
        ctrl = 3'b010; 
        #100;

        in = 8'h55;
        ctrl = 3'b100; 
        #100;

        in = 8'h55;
        ctrl = 3'b011; 
        #100;

        in = 8'h55;
        ctrl = 3'b110; 
        #100;

        in = 8'h55;
        ctrl = 3'b111; 
        #100;

        $display("Passed");
        $finish;
    end

    initial begin
        $monitor("At time %t, in = %h, ctrl = %b, out = %h", $time, in, ctrl, out);
    end

endmodule

module mux2X1(
    input in0,
    input in1,
    input sel,
    output reg out
);
    always @(*) begin
        out = (sel) ? in1 : in0;
    end
endmodule
